    vals=sorted(vals)
    n=len(vals)
    if n==0:
        return None
    mid=n//2
    if n%2==1:
        return vals[mid]
    return (vals[mid-1]+vals[mid])/2

def quantile(vals, q):
    vals=sorted(vals)
    if not vals:
        return None
    # linear interpolation inclusive
    pos=(len(vals)-1)*q
    lo=int(math.floor(pos))
    hi=int(math.ceil(pos))
