def quantile(vals,q):
    vals=sorted(vals)
    if not vals:
        return None
    pos=(len(vals)-1)*q
    lo=int(math.floor(pos))
    hi=int(math.ceil(pos))
    if lo==hi:
        return vals[lo]
    return vals[lo]*(hi-pos)+vals[hi]*(pos-lo)

def median(vals):
    return quantile(vals,0.5)

def mean(vals):
    return sum(vals)/len(vals) if vals else None

def safe_div(a,b):
    return a/b if b else None

p='benchmark/data.csv'
city_total=Counter()
city_room=defaultdict(Counter)
city_price=defaultdict(list)
city_room_price=defaultdict(lambda: defaultdict(list))
city_avail=defaultdict(list)
city_min=defaultdict(list)
city_rpm=defaultdict(list)
