city_last_review=defaultdict(list)

for r in csv.DictReader(open(p, newline='', encoding='utf-8')):
    c=r['city']
    city_total[c]+=1
    room=r['room_type']
    city_room[c][room]+=1
    if room=='Entire home/apt':
        city_entire[c]+=1

    pr=to_float(r['price'])
    if pr is not None:
        city_price[c].append(pr)
        city_room_price[c][room].append(pr)

    av=to_int(r['availability_365'])
    if av is not None:
        city_avail[c].append(av)

    mn=to_int(r['minimum_nights'])
