        city_min[c].append(mn)

    rpm=to_float(r['reviews_per_month'])
    if rpm is not None:
        city_rpm[c].append(rpm)

    chlc=to_int(r['calculated_host_listings_count'])
    if chlc is not None:
        city_count_nonnull[c]+=1
        if chlc>=5:
            city_prof[c]+=1

    nltm=to_int(r['number_of_reviews_ltm'])
    if nltm is not None:
        city_reviews_ltm[c].append(nltm)

    lr=(r['last_review'] or '').strip()
    if lr:
        try:
            city_last_review[c].append(datetime.date.fromisoformat(lr))
        except:
            pass

cities=sorted(city_total)

out={
    'cities': cities,
    'total_listings_by_city': {c: city_total[c] for c in cities},
    'room_type_counts_by_city': {c: dict(city_room[c]) for c in cities},
    'kpis_by_city': {},
    'price_stats_by_city': {},
    'price_stats_by_city_room': {},
    'availability_stats_by_city': {},
    'minimum_nights_stats_by_city': {},
    'demand_stats_by_city': {},
    'last_review_stats_by_city': {},
}

for c in cities:
