        'p75': quantile(city_price[c],0.75),
        'p90': quantile(city_price[c],0.90),
        'min': min(city_price[c]) if city_price[c] else None,
        'max': max(city_price[c]) if city_price[c] else None,
    }
    out['availability_stats_by_city'][c]={
        'p25': quantile(city_avail[c],0.25),
        'p50': quantile(city_avail[c],0.50),
