        'p90': quantile(city_avail[c],0.90),
        'mean': mean(city_avail[c]),
        'max': max(city_avail[c]) if city_avail[c] else None,
    }
    out['minimum_nights_stats_by_city'][c]={
        'p25': quantile(city_min[c],0.25),
        'p50': quantile(city_min[c],0.50),
        'p75': quantile(city_min[c],0.75),
        'p90': quantile(city_min[c],0.90),
        'mean': mean(city_min[c]),
        'max': max(city_min[c]) if city_min[c] else None,
    }
    out['demand_stats_by_city'][c]={
        'avg_reviews_per_month': mean(city_rpm[c]),
        'median_reviews_per_month': median(city_rpm[c]),
        'avg_reviews_ltm': mean(city_reviews_ltm[c]),
        'median_reviews_ltm': median(city_reviews_ltm[c]),
    }
    if city_last_review[c]:
        out['last_review_stats_by_city'][c]={
            'most_recent': str(max(city_last_review[c])),
            'oldest': str(min(city_last_review[c])),
        }
    else:
