import csv, json, math, datetime
from collections import defaultdict, Counter

def to_float(x):
    x=(x or '').strip()
    if x=='':
        return None
    try:
        return float(x)
    except:
        return None

def to_int(x):
    x=(x or '').strip()
    if x=='':
        return None
    try:
        return int(float(x))
    except:
        return None

def quantile(vals,q):
    vals=sorted(vals)
    if not vals:
        return None
    pos=(len(vals)-1)*q
    lo=int(math.floor(pos))
    hi=int(math.ceil(pos))
    if lo==hi:
        return vals[lo]
    return vals[lo]*(hi-pos)+vals[hi]*(pos-lo)

def median(vals):
    return quantile(vals,0.5)

def mean(vals):
    return sum(vals)/len(vals) if vals else None

def safe_div(a,b):
    return a/b if b else None

p='benchmark/data.csv'
city_total=Counter()
city_room=defaultdict(Counter)
city_price=defaultdict(list)
city_room_price=defaultdict(lambda: defaultdict(list))
city_avail=defaultdict(list)
city_min=defaultdict(list)
city_rpm=defaultdict(list)
city_prof=Counter()
city_count_nonnull=Counter()
city_entire=Counter()
city_reviews_ltm=defaultdict(list)
city_last_review=defaultdict(list)

for r in csv.DictReader(open(p, newline='', encoding='utf-8')):
    c=r['city']
    city_total[c]+=1
    room=r['room_type']
    city_room[c][room]+=1
    if room=='Entire home/apt':
        city_entire[c]+=1

    pr=to_float(r['price'])
    if pr is not None:
        city_price[c].append(pr)
        city_room_price[c][room].append(pr)

    av=to_int(r['availability_365'])
    if av is not None:
        city_avail[c].append(av)

    mn=to_int(r['minimum_nights'])
    if mn is not None:
        city_min[c].append(mn)

    rpm=to_float(r['reviews_per_month'])
    if rpm is not None:
        city_rpm[c].append(rpm)

    chlc=to_int(r['calculated_host_listings_count'])
    if chlc is not None:
        city_count_nonnull[c]+=1
        if chlc>=5:
            city_prof[c]+=1

    nltm=to_int(r['number_of_reviews_ltm'])
    if nltm is not None:
        city_reviews_ltm[c].append(nltm)

    lr=(r['last_review'] or '').strip()
    if lr:
        try:
            city_last_review[c].append(datetime.date.fromisoformat(lr))
        except:
            pass

cities=sorted(city_total)

out={
    'cities': cities,
    'total_listings_by_city': {c: city_total[c] for c in cities},
    'room_type_counts_by_city': {c: dict(city_room[c]) for c in cities},
    'kpis_by_city': {},
    'price_stats_by_city': {},
    'price_stats_by_city_room': {},
    'availability_stats_by_city': {},
    'minimum_nights_stats_by_city': {},
    'demand_stats_by_city': {},
    'last_review_stats_by_city': {},
}

for c in cities:
    total=city_total[c]
    priced=len(city_price[c])
    out['kpis_by_city'][c]={
        'total_listings': total,
        'priced_listings': priced,
        'priced_share': safe_div(priced,total),
        'median_price': median(city_price[c]),
        'mean_price': mean(city_price[c]),
        'entire_home_share': safe_div(city_entire[c], total),
        'professional_host_listing_share': safe_div(city_prof[c], city_count_nonnull[c]),
        'avg_reviews_per_month': mean(city_rpm[c]),
        'mean_availability_365': mean(city_avail[c]),
    }
    out['price_stats_by_city'][c]={
        'p25': quantile(city_price[c],0.25),
        'p50': median(city_price[c]),
        'p75': quantile(city_price[c],0.75),
        'p90': quantile(city_price[c],0.90),
        'min': min(city_price[c]) if city_price[c] else None,
        'max': max(city_price[c]) if city_price[c] else None,
    }
    out['availability_stats_by_city'][c]={
        'p25': quantile(city_avail[c],0.25),
        'p50': quantile(city_avail[c],0.50),
        'p75': quantile(city_avail[c],0.75),
        'p90': quantile(city_avail[c],0.90),
        'mean': mean(city_avail[c]),
        'max': max(city_avail[c]) if city_avail[c] else None,
    }
    out['minimum_nights_stats_by_city'][c]={
        'p25': quantile(city_min[c],0.25),
        'p50': quantile(city_min[c],0.50),
        'p75': quantile(city_min[c],0.75),
        'p90': quantile(city_min[c],0.90),
        'mean': mean(city_min[c]),
        'max': max(city_min[c]) if city_min[c] else None,
    }
    out['demand_stats_by_city'][c]={
        'avg_reviews_per_month': mean(city_rpm[c]),
        'median_reviews_per_month': median(city_rpm[c]),
        'avg_reviews_ltm': mean(city_reviews_ltm[c]),
        'median_reviews_ltm': median(city_reviews_ltm[c]),
    }
    if city_last_review[c]:
        out['last_review_stats_by_city'][c]={
            'most_recent': str(max(city_last_review[c])),
            'oldest': str(min(city_last_review[c])),
        }
    else:
        out['last_review_stats_by_city'][c]=None

for c in cities:
    out['price_stats_by_city_room'][c]={}
    for room, vals in city_room_price[c].items():
        out['price_stats_by_city_room'][c][room]={
            'n': len(vals),
            'median': median(vals),
            'mean': mean(vals),
        }

print(json.dumps(out, indent=2))
